#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# Bearers are typed hidden and never saved: ENV_FILE points at a non-file so
# ask_secret never reads or offers a stored value, and nothing calls write_env.
ENV_FILE=/dev/null

BASE="https://mzjsuvatrzhciojmbbbm.supabase.co/functions/v1"
STAGING_REF="mzjsuvatrzhciojmbbbm"
PROD_REF="zvoijyneresvkadpprel"
REPO="davidcastelnuovo/aios"
SECRETS_URL="https://supabase.com/dashboard/project/${STAGING_REF}/functions/secrets"
TASK="Connectivity test only. Reply OK and make no changes."

PASS=()
FAIL=()
record() { # record pass|fail "label"
  if [[ "$1" == pass ]]; then PASS+=("$2"); printf '  %s✓ PASS%s %s\n' "$GREEN" "$RESET" "$2"
  else FAIL+=("$2"); printf '  %s✗ FAIL%s %s\n' "$RED" "$RESET" "$2"; fi
}

# rpc FUNCTION BEARER → prints the raw response body of a request_dev_task call.
rpc() {
  curl -sS --max-time 90 -X POST "$BASE/$1" \
    -H "Authorization: Bearer $2" \
    -H 'Content-Type: application/json' -H 'Accept: application/json' \
    -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"request_dev_task\",\"arguments\":{\"task\":\"$TASK\"}}}" \
    2>&1 || true
}
snippet() { printf '%s' "$1" | tr '\n' ' ' | cut -c1-300; }
urls() { printf '%s' "$1" | grep -oE 'https://[^" \\]+' | sort -u || true; }

# Staging only: refuse anything that points at Production.
if [[ "$BASE" == *"$PROD_REF"* ]]; then
  printf 'Refusing to run: BASE points at the Production project.\n' >&2
  exit 1
fi

# ── Logs: a shareable folder with every response and answer. Bearers are
# redacted before anything is written. ──────────────────────────────────────
LOG_DIR="${LOG_DIR:-verify-logs/$(date +%Y%m%d-%H%M%S)}"
mkdir -p "$LOG_DIR/responses"
EVENTS="$LOG_DIR/events.log"
: > "$EVENTS"
_redact() {
  local t="$1" v
  for v in "$CURSOR_MCP_BEARER" "$GROK_MCP_BEARER" "$MANUS_MCP_BEARER"; do
    [[ -n "$v" ]] && t="${t//"$v"/<redacted>}"
  done
  printf '%s' "$t"
}
log() { printf '%s  %s\n' "$(date +%H:%M:%S)" "$(_redact "$1")" >> "$EVENTS"; }
# save_response LABEL BODY writes the raw response to responses/LABEL.json
save_response() {
  _redact "$2" > "$LOG_DIR/responses/${1//[^A-Za-z0-9._-]/_}.json"
  printf '\n' >> "$LOG_DIR/responses/${1//[^A-Za-z0-9._-]/_}.json"
}
# Wrap library functions so every stage, result and y/N answer is logged.
eval "_lib_stage() $(declare -f stage | tail -n +2)"
stage() { _lib_stage "$1"; log "STAGE $_STAGE_INDEX/$TOTAL_STAGES: $1"; }
eval "_lib_record() $(declare -f record | tail -n +2)"
record() { _lib_record "$1" "$2"; log "$(printf %s "$1" | tr a-z A-Z): $2"; }
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  log "ASK: $1 -> ${reply:-<blank>}"
  [[ "$reply" =~ ^[Yy] ]]
}
log "run start; BASE=$BASE"

banner "Verify GITHUB_REPO on Staging (PR #858)"

# ── Stage 0 ───────────────────────────────────────────────────────────────
stage "Prerequisites"
say "Staging project: $STAGING_REF (Production $PROD_REF is refused)."
open_url "$SECRETS_URL"
step "Make sure GITHUB_REPO is NOT set on Staging (delete it if present). The negative test runs first."
step "Set CURSOR_AUTO_CREATE_PR = false for the duration of this test."
warn "Note the previous CURSOR_AUTO_CREATE_PR value (or 'unset') so you can restore it at the end."
pause "GITHUB_REPO absent and CURSOR_AUTO_CREATE_PR=false? (wait ~10s after deleting, then press Enter)"
say "Enter the bearers set on Staging (hidden, never saved). Supabase never shows secret values."
note "If CURSOR_MCP_BEARER / GROK_MCP_BEARER / MANUS_MCP_BEARER are not in the secrets list, leave them blank."
note "If they are set and you don't have them, see: select oauth_tokens->>'bearer' from agent_mcp_connections where state='ready' (Staging SQL editor)."
ask_secret CURSOR_MCP_BEARER "CURSOR_MCP_BEARER:"
ask_secret GROK_MCP_BEARER "GROK_MCP_BEARER (Enter to reuse the cursor bearer):"
[[ -z "$GROK_MCP_BEARER" ]] && GROK_MCP_BEARER="$CURSOR_MCP_BEARER"
ask_secret MANUS_MCP_BEARER "MANUS_MCP_BEARER:"
[[ -n "$CURSOR_MCP_BEARER" && -n "$MANUS_MCP_BEARER" ]] || warn "blank bearer: only works if that secret is NOT set on Staging (the function then accepts any caller)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Negative test: GITHUB_REPO unset"
say "GITHUB_REPO is unset, so each tool must fail with a clear error before launching anything."
for fn in cursor-mcp grok-mcp manus-mcp; do
  case "$fn" in
    cursor-mcp) b="$CURSOR_MCP_BEARER" ;;
    grok-mcp)   b="$GROK_MCP_BEARER" ;;
    manus-mcp)  b="$MANUS_MCP_BEARER" ;;
  esac
  out=$(rpc "$fn" "$b")
  save_response "negative-$fn" "$out"
  if [[ "$out" == *"GITHUB_REPO is not set"* ]]; then
    record pass "negative: $fn reports missing GITHUB_REPO"
  else
    record fail "negative: $fn did not report missing GITHUB_REPO"
    note "response: $(snippet "$out")"
  fi
done
open_url "$SECRETS_URL"
step "Now create GITHUB_REPO = $REPO on Staging."
pause "Created? (wait ~10s, then press Enter)"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Positive test: real dispatch via MCP"
warn "This launches a real Cursor agent, Grok session and Manus task with a no-change prompt."
if confirm "Run the three live calls now?"; then
  for fn in cursor-mcp grok-mcp manus-mcp; do
    case "$fn" in
      cursor-mcp) b="$CURSOR_MCP_BEARER" ;;
      grok-mcp)   b="$GROK_MCP_BEARER" ;;
      manus-mcp)  b="$MANUS_MCP_BEARER" ;;
    esac
    out=$(rpc "$fn" "$b")
    save_response "positive-$fn" "$out"
    if [[ "$out" == *"GITHUB_REPO is not set"* || "$out" == *"❌"* || "$out" == *'"isError":true'* || -z "$out" ]]; then
      record fail "positive: $fn dispatch"
      note "response: $(snippet "$out")"
    else
      record pass "positive: $fn dispatch"
      urls "$out" | while read -r u; do note "  link: $u"; done
    fi
  done
  say "cursor-mcp and grok-mcp: if CURSOR_CLOUD_ENV_NAME is set, the agent's repo comes from that Cursor"
  say "environment, not from GITHUB_REPO. The call succeeding proves GITHUB_REPO was read."
  step "Open the Manus task link above and check the prompt contains: Repository: $REPO"
  if confirm "Does the Manus prompt show 'Repository: $REPO'?"; then
    record pass "manus prompt contains repository"
  else
    record fail "manus prompt contains repository"
  fi
else
  record fail "positive MCP dispatch (skipped)"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Carmen UI"
say "Carmen is enabled for you. Ask her to run request_dev_task."
step "Open the app on Staging/Preview at /t/<tenant-slug>/agents or use the Carmen header buttons."
step "Ask Carmen: \"Run request_dev_task with the task: $TASK\""
if confirm "Did Carmen return an agent/session/task link without a GITHUB_REPO error?"; then
  record pass "carmen request_dev_task"
else
  record fail "carmen request_dev_task"
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "cursor-generate-creative"
note "GITHUB_REPO is only read here when CURSOR_CLOUD_ENV_NAME is empty."
if confirm "Is CURSOR_CLOUD_ENV_NAME set on Staging?"; then
  warn "With it set, this path never reads GITHUB_REPO; the check below only confirms the function runs."
fi
step "In the app, generate one creative (Creative department)."
if confirm "Did generation start an agent / return a link without error?"; then
  record pass "cursor-generate-creative"
else
  record fail "cursor-generate-creative"
fi

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Frontend on the PR Preview"
say "Needs VITE_GITHUB_REPO = $REPO set in Vercel for Preview (and the Preview redeployed after setting it)."
open_url "https://github.com/davidcastelnuovo/aios/pull/858"
step "Open the Vercel Preview link from the PR (the 'src' / 'after-lead' project, per your app)."
step "Open an automation step config, expand 'הצג JSON לדוגמה', hover the guide link."
if confirm "Does the link end in $REPO/blob/main/docs/manychat-flow-remap-guide.md?"; then
  record pass "manychat guide link"
else
  record fail "manychat guide link"
fi
step "Open /t/<tenant-slug>/github-agent on the Preview."
if confirm "Is the repo field prefilled with $REPO?"; then
  record pass "github-agent panel prefill"
else
  record fail "github-agent panel prefill"
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Cleanup and summary"
open_url "$SECRETS_URL"
step "Restore CURSOR_AUTO_CREATE_PR to its previous value (or delete it if it was unset)."
step "Confirm GITHUB_REPO = $REPO is set on Staging."
pause "Done?"
printf '\n  %sResults%s\n' "$BOLD" "$RESET"
(( ${#PASS[@]} )) && for p in "${PASS[@]}"; do printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$p"; done
(( ${#FAIL[@]} )) && for f in "${FAIL[@]}"; do printf '  %s✗%s %s\n' "$RED" "$RESET" "$f"; done
printf '\n  %s%s passed, %s failed%s\n' "$BOLD" "${#PASS[@]}" "${#FAIL[@]}" "$RESET"
{
  printf 'Passed (%s):\n' "${#PASS[@]}"; (( ${#PASS[@]} )) && printf '  - %s\n' "${PASS[@]}"
  printf 'Failed (%s):\n' "${#FAIL[@]}"; (( ${#FAIL[@]} )) && printf '  - %s\n' "${FAIL[@]}"
} > "$LOG_DIR/summary.txt"
log "run end: ${#PASS[@]} passed, ${#FAIL[@]} failed"
pause "Press Enter to finish"

finish
note "logs saved to: $(cd "$LOG_DIR" && pwd)"
